# REVIEWED
# problem P-fd59f2 (generated by opus): Let $r_3(N)$ be the largest size of a set $A\subseteq[N]=\{1,\dots,N\}$ with no non-trivial 3-term arithmetic progression $x,x+d,x+2d$ ($d\ne0$). Behrend's construction, together with its later constant-factor refinements, gives $r_3(N)\ge N\exp(-C\sqrt{\log N})$. Construct, for some fixed $\gamma<1
# finite_form: For $N=1000$: find a set $A\subseteq\{1,\dots,1000\}$ with $|A|\ge 140$ containing no non-trivial 3-term arithmetic progression. The base-3 digit construction (digits in $\{0,1\}$) gives only about 113 elements, and the exact value of $r_3(1000)$ is unknown.
# candidate_format: a JSON array of at least 140 distinct integers, each between 1 and 1000 inclusive

def check(candidate) -> bool:
    try:
        if not isinstance(candidate, list):
            return False
        vals = []
        for x in candidate:
            if isinstance(x, bool) or not isinstance(x, int):
                return False
            if x < 1 or x > 1000:
                return False
            vals.append(x)
        s = set(vals)
        if len(s) != len(vals):
            return False
        if len(vals) < 140:
            return False
        v = sorted(vals)
        n = len(v)
        for i in range(n):
            a = v[i]
            for j in range(i + 1, n):
                c = v[j]
                if (a + c) % 2 == 0 and (a + c) // 2 in s:
                    return False
        return True
    except Exception:
        return False
